{
  "openapi": "3.0.1",
  "info": {
    "title": "Mem0 API Docs",
    "version": "v1"
  },
  "paths": {
    "/v1/memories/{memory_id}/": {
      "get": {
        "operationId": "memories_read",
        "responses": {
          "200": {
            "description": "OK",
            "content": {
              "application/json": {
                "schema": {
                  "type": "object",
                  "properties": {
                    "id": {
                      "type": "string",
                      "format": "uuid",
                      "description": "Unique identifier for the memory."
                    },
                    "memory": {
                      "type": "string",
                      "description": "The content of the memory"
                    },
                    "user_id": {
                      "type": "string",
                      "nullable": true,
                      "description": "Identifier of the user associated with this memory"
                    },
                    "agent_id": {
                      "type": "string",
                      "nullable": true,
                      "description": "The identifier of the agent associated with this memory, if any."
                    },
                    "created_at": {
                      "type": "string",
                      "format": "date-time",
                      "description": "Timestamp of when the memory was created."
                    },
                    "updated_at": {
                      "type": "string",
                      "format": "date-time",
                      "description": "Timestamp of when the memory was last updated."
                    },
                    "expiration_date": {
                      "type": "string",
                      "format": "date",
                      "nullable": true,
                      "description": "The date when the memory will expire. Format: YYYY-MM-DD."
                    },
                    "replaced_by": {
                      "type": "string",
                      "nullable": true,
                      "description": "ID of the memory that superseded this one, if any."
                    },
                    "synthesized": {
                      "type": "boolean",
                      "description": "Whether this memory was synthesized rather than directly extracted."
                    },
                    "lifecycle_state": {
                      "type": "string",
                      "description": "Lifecycle state of the memory."
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

postgres.content:
CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE users (id uuid PRIMARY KEY, name text NOT NULL, email text);
CREATE TABLE agents (id uuid PRIMARY KEY, name text NOT NULL);
CREATE TABLE conversations (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users (id), started_at timestamptz NOT NULL);
CREATE TABLE messages (
  id uuid PRIMARY KEY,
  conversation_id uuid NOT NULL REFERENCES conversations (id),
  user_id uuid REFERENCES users (id),
  role text NOT NULL CHECK (role IN ('user', 'assistant', 'system')),
  content text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TYPE memory_state AS ENUM ('active', 'superseded', 'forgotten');
CREATE TYPE memory_origin AS ENUM ('user_stated', 'assistant_inferred', 'admin_added', 'imported');
CREATE TABLE memories (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users (id),
  agent_id uuid REFERENCES agents (id),
  source_conversation_id uuid REFERENCES conversations (id),
  superseded_by uuid REFERENCES memories (id),
  content text NOT NULL,
  state memory_state NOT NULL DEFAULT 'active',
  origin memory_origin NOT NULL,
  embedding vector(1536),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz,
  forgotten_at timestamptz
);
CREATE TABLE memory_events (
  id uuid PRIMARY KEY,
  memory_id uuid NOT NULL REFERENCES memories (id),
  event text NOT NULL CHECK (event IN ('created', 'edited', 'superseded', 'forgotten')),
  at timestamptz NOT NULL
);

